insert into flashcards (id, team_id, case_id, deck, front, back, citation_ids, created_at, created_by, truth_item_id, source_kind, updated_at) values
  ('cfe05ac6-fe7b-4f48-888e-fcf92f66f2c9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'Anthropic, maker of Claude, negotiated with the U.S. government over military use of its AI, holding two limits: no lethal autonomous warfare without human oversight, and no mass surveillance of Americans (Reuters, March 2026)', array['94d1cca5-06fe-4263-869b-2a803599aa06']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '94d1cca5-06fe-4263-869b-2a803599aa06', 'truth', '2026-11-01T00:00:00.000Z'),
  ('f10d09a4-d303-4b43-b18c-c514902abcfd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'After the government objected, Anthropic sued, claiming it was unlawfully punished for refusing to remove its safety guardrails (Sriram, Reuters, March 9, 2026)', array['84871b0e-e6e5-43ed-8ba9-dd9eeae2adf7']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '84871b0e-e6e5-43ed-8ba9-dd9eeae2adf7', 'truth', '2026-11-01T00:00:00.000Z'),
  ('08ebba5c-d305-4874-ac5b-a03b5fc2b945', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'CEO Dario Amodei is not opposed to AI weapons in principle; his concern is that current systems aren''t reliable enough (Seetharaman, Reuters, March 4, 2026)', array['5c82f376-7a87-4740-aa4c-d5a1f90b08cd']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '5c82f376-7a87-4740-aa4c-d5a1f90b08cd', 'truth', '2026-11-01T00:00:00.000Z'),
  ('2d256009-901a-4998-a8cf-1aa6e30135d2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'Pentagon view: AI is a neutral tool, like Excel; the military should be bound by U.S. law, elected officials and the chain of command, not company policies (Case text)', array['e2294937-4e35-48ed-b634-89357b47238d']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'e2294937-4e35-48ed-b634-89357b47238d', 'truth', '2026-11-01T00:00:00.000Z'),
  ('63338095-6be4-4aff-a70f-f374d9997248', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'A May 1, 2026 Department of War release said AI would speed data synthesis and support warfighter decisions (Department of War)', array['de9bf774-8f4f-46a2-b660-d2e36c6ba03b']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'de9bf774-8f4f-46a2-b660-d2e36c6ba03b', 'truth', '2026-11-01T00:00:00.000Z'),
  ('671d0c9c-3e40-44ef-8912-f8a665a9435b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'A wargame pitting GPT-5.2, Claude Sonnet 4 and Gemini 3 ended in a tactical nuclear strike in 95% of games; models treated tactical nuclear use as a manageable risk (Tom''s Hardware, Feb 26, 2026)', array['94647011-a377-458d-9aef-aeb51e4a56e3']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '94647011-a377-458d-9aef-aeb51e4a56e3', 'truth', '2026-11-01T00:00:00.000Z'),
  ('e83d33a2-2a76-475a-9ee6-a30a44cf62c2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'For AI: war is already full of human error, bias, panic and fatigue; AI may reduce mistakes; refusing it could be irresponsible (Case text)', array['c3ecb231-6783-46e2-a50f-9346153a5ea3']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'c3ecb231-6783-46e2-a50f-9346153a5ea3', 'truth', '2026-11-01T00:00:00.000Z'),
  ('cf720d0c-4481-4e14-bc47-52e5e79a6438', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'Against: AI changes the moral character of decisions, adds distance, invites overreliance by humans "in the loop," and makes war easier to start (Case text)', array['cd41db40-5e11-4ddb-8b67-af92320229a9']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'cd41db40-5e11-4ddb-8b67-af92320229a9', 'truth', '2026-11-01T00:00:00.000Z'),
  ('f5b5448f-eb4d-43a7-9163-bb4a1852c974', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Fact with citation', 'Closing question: if a future AI were as accurate as or more accurate than human analysts, would the ethical objection disappear? (Case text)', array['8e311c9b-cdc3-45aa-aad2-84809f3f2570']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '8e311c9b-cdc3-45aa-aad2-84809f3f2570', 'truth', '2026-11-01T00:00:00.000Z'),
  ('54fc382f-74ea-4841-ae3f-b49deed06a5a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Framework (one sentence)', 'Robert Sparrow, Killer Robots (2007): philosopher Robert Sparrow''s "Killer Robots" (2007) argues that just war requires someone who can be held responsible for each death. Our team put it simply: letting AI use weapons turns a moral decision into a program.', array['56e7f307-0dfe-4b3f-ace8-231282d61260']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '56e7f307-0dfe-4b3f-ace8-231282d61260', 'truth', '2026-11-01T00:00:00.000Z'),
  ('00c3d1b4-4b28-4830-a639-931bf7b3650c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Framework (one sentence)', 'Kant, humanity formula: Kant''s humanity formula (never treat people merely as tools or data points) explains why a target is owed a human judgment.', array['25099124-2a14-4aee-886d-739d1d3354fc']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '25099124-2a14-4aee-886d-739d1d3354fc', 'truth', '2026-11-01T00:00:00.000Z'),
  ('b40e1637-999a-46ec-aba5-16432159b9ef', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Framework (one sentence)', 'Chilling-effect argument: this is a chilling-effect argument rooted in privacy and free-association values. A limit on domestic mass surveillance protects the democratic accountability that gives the military its authority.', array['d0a5b60d-5900-45fd-a842-8a31a9db7edc']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'd0a5b60d-5900-45fd-a842-8a31a9db7edc', 'truth', '2026-11-01T00:00:00.000Z'),
  ('b178fb48-9bf7-4f2a-a8d4-815615c05da6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Framework (one sentence)', 'Virtue ethics: Virtue ethics asks what a responsible builder does; the answer includes refusing to sell for uses it believes are wrong.', array['812eb2e5-de42-4dcc-ad49-ec7ceb65c6a1']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '812eb2e5-de42-4dcc-ad49-ec7ceb65c6a1', 'truth', '2026-11-01T00:00:00.000Z'),
  ('76f73745-bd2d-4b3f-91ab-c70fa5d7dfc9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Vivid example for this case', 'the team''s progression: hands, knife, bow, gun, drone, AI. The case notes drone warfare already distances a country from its soldiers'' danger, and that efficient, low-risk war may be easier to start and harder to restrain.', array['6d8d0985-5046-4efd-9d66-bd207d98674e']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '6d8d0985-5046-4efd-9d66-bd207d98674e', 'truth', '2026-11-01T00:00:00.000Z'),
  ('26ba111e-7a6d-4d37-b4a0-d3a7e16979fb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'case-1', 'Vivid example for this case', 'in 2018 Google employees protested the Pentagon''s Project Maven drone-imagery program, and Google declined to renew the contract. Conscientious refusal by builders has precedent.', array['cab91a5e-b19a-4f0b-8cd5-1df1f8469e71']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'cab91a5e-b19a-4f0b-8cd5-1df1f8469e71', 'truth', '2026-11-01T00:00:00.000Z'),
  ('23455a1c-eae8-4153-9428-17e5bf542d0a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'In 2018 Osaka cut its sister-city ties with San Francisco over a statue honoring "comfort women" (BBC News, April 4, 2018)', array['e7ad222b-e63c-44a0-9c42-f590cffaf31a']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', 'e7ad222b-e63c-44a0-9c42-f590cffaf31a', 'truth', '2026-11-01T00:00:00.000Z'),
  ('71cfcab9-ae1a-4cb2-b515-44b3cc2a859b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', '"Comfort women" were women trafficked and sexually abused by the Japanese Imperial Army during World War II (Case text)', array['989b219b-d4ba-4354-a42d-26258e1c1e57']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '989b219b-d4ba-4354-a42d-26258e1c1e57', 'truth', '2026-11-01T00:00:00.000Z'),
  ('d04087b0-7358-422d-87bd-28aa9db84f6a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'The statue, "Women''s Column of Strength," stands near San Francisco''s Chinatown and honors thousands of Korean and Chinese women and all women affected by such crimes (World Heritage USA)', array['29b5e7af-d211-4327-9a5f-82b9df3487ce']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '29b5e7af-d211-4327-9a5f-82b9df3487ce', 'truth', '2026-11-01T00:00:00.000Z'),
  ('367c7f54-c0c6-4296-940a-852af5849014', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'The memorial''s stated values: memory, dialogue, peace and reconciliation, transformation and justice (World Heritage USA)', array['2a86825a-10b6-49e7-9ad9-c6802386dff6']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2a86825a-10b6-49e7-9ad9-c6802386dff6', 'truth', '2026-11-01T00:00:00.000Z'),
  ('71d4a2ce-4545-40ed-9eaf-abf6f2c23414', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'Japan''s embassy objected to a similar planned statue in New Zealand, warning of diplomatic harm; the council rejected it, citing lack of public support (BBC and Reuters, April 2026)', array['c6dca5c8-986f-4d8b-a212-fec920176971']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', 'c6dca5c8-986f-4d8b-a212-fec920176971', 'truth', '2026-11-01T00:00:00.000Z'),
  ('fa66760d-f2a0-4da0-9b69-3f60cdff17a4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'New Zealand opponents cited community tension, political readings and relevance; supporters cited reflection, acknowledging harm and education (Case text)', array['043a35ea-e987-4cbc-b589-09b913069819']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '043a35ea-e987-4cbc-b589-09b913069819', 'truth', '2026-11-01T00:00:00.000Z'),
  ('d9d82c5b-36d5-4568-a153-b9854965a414', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'Japan has offered few apologies or reparations that survivors consider satisfactory (Comfort Women Justice Coalition)', array['4b4610ff-bc6e-4744-8424-af8ec1456878']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '4b4610ff-bc6e-4744-8424-af8ec1456878', 'truth', '2026-11-01T00:00:00.000Z'),
  ('36be48f2-4dc8-4a45-9e6f-726e9e3c13ff', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'San Francisco has far larger Chinese and Korean communities than New Zealand, and the U.S. military reportedly took part in the abuse; New Zealand had no such involvement (NBC News, April 27, 2007)', array['8273a190-ac81-45c5-a89f-bcad04ae59ef']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '8273a190-ac81-45c5-a89f-bcad04ae59ef', 'truth', '2026-11-01T00:00:00.000Z'),
  ('52978652-62a5-47af-801f-d02904b4c907', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'Both countries should examine monuments to their own wrongs: many U.S. statues honor conquistadors and Confederates, few honor Native Americans or enslaved people, and plantations operate as wedding venues (Case text)', array['fce0fabc-ef27-4739-a1c4-be21c1e084c2']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', 'fce0fabc-ef27-4739-a1c4-be21c1e084c2', 'truth', '2026-11-01T00:00:00.000Z'),
  ('66e4fb5f-2f31-4195-8206-c559ed59fe39', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Fact with citation', 'Framing question: how should governments decide which events to memorialize, weighing culpability, resources and national memory? (Case text)', array['30b1ea62-19be-4edd-9abf-230de136b397']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '30b1ea62-19be-4edd-9abf-230de136b397', 'truth', '2026-11-01T00:00:00.000Z'),
  ('e3acad99-32d9-48e3-8d06-b8f196d2a70f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Framework (one sentence)', 'Margalit, The Ethics of Memory: corrective justice says whoever is wronged is owed repair; philosopher Avishai Margalit''s *The Ethics of Memory* (2002) argues that communities have duties to remember grave wrongs. The case reports that survivors consider Japan''s apologies and reparations unsatisfactory.', array['3bbfc54d-a0aa-41db-aac8-549b37137022']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '3bbfc54d-a0aa-41db-aac8-549b37137022', 'truth', '2026-11-01T00:00:00.000Z'),
  ('6f8bdfc3-c413-4bcf-a528-3d7804ae8cee', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Framework (one sentence)', 'Kant, humanity formula: Kant''s humanity formula supports the victims: their suffering can''t be treated as a bargaining chip in diplomatic relations.', array['5cb061b8-6959-408c-be89-7125ad57e7bf']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '5cb061b8-6959-408c-be89-7125ad57e7bf', 'truth', '2026-11-01T00:00:00.000Z'),
  ('37555035-b880-4f29-a24c-32e18d19dee7', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Framework (one sentence)', 'Kant, universalizability: Kant''s universalizability test: act only on a rule everyone could follow. The case notes many U.S. statues honor conquistadors and Confederate leaders while few honor Native Americans or enslaved people.', array['3ceb3184-12f6-4d58-93e1-09cc5f7c13c7']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '3ceb3184-12f6-4d58-93e1-09cc5f7c13c7', 'truth', '2026-11-01T00:00:00.000Z'),
  ('70521a2f-a77e-4765-8e97-e3f0708c0481', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Framework (one sentence)', 'Khader, Decolonizing Universalism: New Zealand''s council rejected its statue for lack of local support, while San Francisco''s communities wanted theirs; the same test gives different answers. Serene Khader''s *Decolonizing Universalism* (in the team''s resources) argues we can hold universal values against injustice without imposing one culture''s way of expressing them.', array['b8a499fc-4bf8-46a0-8cb6-0a3377d6dadb']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', 'b8a499fc-4bf8-46a0-8cb6-0a3377d6dadb', 'truth', '2026-11-01T00:00:00.000Z'),
  ('f232d1b1-4e6c-45fc-8707-e5c4b1f23fbd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Who said / where: recall this quote', 'in practice we put it this way: the goal is "not to shame a country, but to show what people are capable of."', array['4e2c4479-af43-4505-b565-2d9cfd4f7e39']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '4e2c4479-af43-4505-b565-2d9cfd4f7e39', 'truth', '2026-11-01T00:00:00.000Z'),
  ('7ce7dde8-4381-4506-a2e1-38b2311db753', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'case-3', 'Vivid example for this case', 'Germany''s public memory of the Holocaust, including Berlin''s Memorial to the Murdered Jews of Europe and preserved camps used as public history, which the case contrasts with U.S. plantations used as wedding venues. Our team flagged Germany as the model: acknowledgment, remediation, and no denial.', array['477cbec4-4bc8-4a3e-b650-88b3e1927244']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '477cbec4-4bc8-4a3e-b650-88b3e1927244', 'truth', '2026-11-01T00:00:00.000Z'),
  ('12694bbb-d6e9-4fc0-a572-4b618cf5fa9c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'case-4', 'Fact with citation', 'Clavicular (Braden Peters), a 20-year-old influencer, is part of an online community that embraces "maxxing" appearance (Bernstein, *NYT*, Feb 13, 2026)', array['6a617d88-7109-4ace-a25e-10671f525bd0']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '6a617d88-7109-4ace-a25e-10671f525bd0', 'truth', '2026-11-01T00:00:00.000Z'),
  ('6c7eb046-8162-4216-8b0d-9a48a8452f22', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'case-4', 'Fact with citation', 'The movement holds that male attractiveness drives worldly success (Case text)', array['73c5bbf5-8979-4605-b40c-6ea4b5c66ffb']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '73c5bbf5-8979-4605-b40c-6ea4b5c66ffb', 'truth', '2026-11-01T00:00:00.000Z'),
  ('0020fa72-8541-4576-8366-e8fd2ef4d53b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'case-4', 'Fact with citation', '"Softmaxxing" means grooming; "hardmaxxing" means procedures like double-jaw surgery, rhinoplasty, cheek implants and eyelid surgery (Case text)', array['f2ab5f05-0223-478f-854c-e4a5559ac3f5']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', 'f2ab5f05-0223-478f-854c-e4a5559ac3f5', 'truth', '2026-11-01T00:00:00.000Z'),
  ('2959fff6-1fd0-42ce-8f8a-f4b03a2ec94f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'case-4', 'Fact with citation', 'Looksmaxxing mainly targets male adolescents and young adults and builds on "pretty privilege" (Case text)', array['8f7f3b66-f309-4b82-8893-b435c1910395']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '8f7f3b66-f309-4b82-8893-b435c1910395', 'truth', '2026-11-01T00:00:00.000Z'),
