  ('0421d93f-17c8-4488-8e92-215867d12492', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'case-11', 'Fact with citation', 'A 2013 email from Boris Nikolic discussed paying Afghan tribal leaders to support a polio drive and called diversion "super OK"; Gates was more reluctant (Case text)', array['05baa03d-5649-433e-85d4-a0531e9b92f3']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '05baa03d-5649-433e-85d4-a0531e9b92f3', 'truth', '2026-11-01T00:00:00.000Z'),
