  ('d9a86837-b5c6-462e-839b-ddf7190410ef', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'case-12', 'Framework (one sentence)', 'Mill, harm principle: Mill''s harm principle; Article 19(3) of the International Covenant on Civil and Political Rights, which China signed in 1998, allows limits necessary for public health.', array['b10fd347-9dcd-493c-b10c-10ff65c15b25']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'b10fd347-9dcd-493c-b10c-10ff65c15b25', 'truth', '2026-11-01T00:00:00.000Z'),
  ('af630866-c06b-4257-b46f-89a972eba6d1', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'case-12', 'Framework (one sentence)', 'Nguyen, trust: C. Thi Nguyen on trust (from our resources): faking expertise exploits a trust we can''t avoid giving. The grammar test separates claims ("X causes Y," "do this to cure Z") from anecdotes ("I tried this") and values ("trust natural remedies").', array['00e2e8a4-547f-49d1-af6d-56b61d4fd1e6']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '00e2e8a4-547f-49d1-af6d-56b61d4fd1e6', 'truth', '2026-11-01T00:00:00.000Z'),
  ('449abbda-2d83-46b0-bc31-d318dab538d8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'case-12', 'Framework (one sentence)', 'Mill, On Liberty: Mill, *On Liberty*, ch. 2. Semmelweis''s handwashing was rejected in the 1840s; the bacterial cause of ulcers won a 2005 Nobel after doubt; Li Wenliang''s warning was labeled a rumor. Miranda Fricker''s epistemic injustice: credential gates can discount patients'' and traditional communities'' knowledge (the team''s Flonase example).', array['9137b568-f1c8-45be-bd0c-d75e833224b7']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '9137b568-f1c8-45be-bd0c-d75e833224b7', 'truth', '2026-11-01T00:00:00.000Z'),
  ('cdf4717c-da4d-4839-beaa-d71bd8a7bd61', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'case-12', 'Who said / where: recall this quote', 'credential tags let viewers judge; Google already holds "Your Money or Your Life" pages to a higher bar. Licensing fails because credentials don''t guarantee truth (Purdue''s 2007 plea).', array['ddad435e-9296-4750-ae50-b65102465413']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', 'ddad435e-9296-4750-ae50-b65102465413', 'truth', '2026-11-01T00:00:00.000Z'),
  ('9938e8ff-232e-4e8d-9e31-4f5ca04da720', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'case-13', 'Fact with citation', '"Stochastic terrorism": an influential speaker spreads rhetoric that statistically raises the likelihood of violence, usually by a lone actor the speaker doesn''t know (Amman and Meloy, *Perspectives on Terrorism*, 2021)', array['c7cc8b15-12b4-4623-b974-67b4ab4e2f00']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', 'c7cc8b15-12b4-4623-b974-67b4ab4e2f00', 'truth', '2026-11-01T00:00:00.000Z'),
  ('d1b20ce2-d8cd-4327-bd37-b047e3623eb4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'case-13', 'Fact with citation', 'It works through hostile, dehumanizing, escalating rhetoric; it inspires but does not direct; the attack is "statistically predictable but individually unpredictable" (Same)', array['abe96a41-d147-4ef9-8605-a5fae7b25e22']::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', 'abe96a41-d147-4ef9-8605-a5fae7b25e22', 'truth', '2026-11-01T00:00:00.000Z'),
